-- Pruebas sintéticas de integridad V3; todos los datos se revierten.
BEGIN;
SET search_path=geocattle_v3,public;
CREATE FUNCTION pg_temp.assert_true(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'FALLO: %',label; END IF; RAISE NOTICE 'OK: %',label; END $$;
CREATE FUNCTION pg_temp.expect_error(query text,label text,expected text DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$ DECLARE caught boolean:=false; actual text; BEGIN BEGIN EXECUTE query; EXCEPTION WHEN OTHERS THEN caught:=true; GET STACKED DIAGNOSTICS actual=RETURNED_SQLSTATE; IF expected IS NOT NULL AND actual<>expected THEN RAISE EXCEPTION 'SQLSTATE inesperado para %: %',label,actual; END IF; END; IF NOT caught THEN RAISE EXCEPTION 'FALLO (debio rechazar): %',label; END IF; RAISE NOTICE 'OK: %',label; END $$;
SELECT pg_temp.assert_true((SELECT count(*) FROM assignments)=2,'01 reasignacion sin solapamiento conserva historia');
SELECT pg_temp.expect_error($q$INSERT INTO assignments(farm_id,animal_holding_id,animal_id,device_id,assigned_by,valid_from) VALUES('eab52320-d49e-54e6-a56f-0aac26b96b2b','95c2c19d-132b-5f6d-8a15-1805e14704f8','f2935e9e-e433-51fa-8d4d-a0a26d898f7b','97d6dd52-ea04-5bfd-b441-f0362dac754c','63e02029-ff09-549d-a85a-5d8641a63193',now())$q$,'02 collar no se asigna simultaneamente a dos animales','23P01');
SELECT pg_temp.expect_error($q$INSERT INTO assignments(farm_id,animal_holding_id,animal_id,device_id,assigned_by,valid_from) VALUES('eab52320-d49e-54e6-a56f-0aac26b96b2b','95c2c19d-132b-5f6d-8a15-1805e14704f8','f2935e9e-e433-51fa-8d4d-a0a26d898f7b','aef32475-8e72-5c82-a9cc-cc930dd12b9e','63e02029-ff09-549d-a85a-5d8641a63193',now())$q$,'03 collar de otro predio rechazado','23503');
SELECT pg_temp.expect_error($q$INSERT INTO animal_holdings(farm_id,animal_id,valid_from,reason) VALUES('e731cd32-45f6-5c27-867c-c40e0d50780b','f2935e9e-e433-51fa-8d4d-a0a26d898f7b',now(),'traslado')$q$,'04 permanencias solapadas rechazadas','23P01');
SELECT pg_temp.expect_error($q$INSERT INTO farms(account_id,name) VALUES('3011abe0-6d5c-55c7-a849-237a46c59b72','Exceso')$q$,'05 cupo predial aplicado','P0001');
SELECT pg_temp.expect_error($q$INSERT INTO animals(diio,sex,production_type) VALUES('00001','female','milk')$q$,'06 DIIO duplicado rechazado','23505');
SELECT pg_temp.expect_error($q$INSERT INTO geofences(farm_id,sector_id,version,geometry,created_by,valid_from) VALUES('e731cd32-45f6-5c27-867c-c40e0d50780b','55e19728-afd5-52c0-b36a-5d9a6c8aeb39',1,ST_GeomFromText('POLYGON((0 0,1 0,0 1,0 0))',4326),'1886724f-5b09-5ec6-a6fd-f7bab0df80cc',now())$q$,'07 triangulo rechazado: minimo cuatro vertices','P0001');
SELECT pg_temp.expect_error($q$UPDATE geofences SET geometry=ST_GeomFromText('POLYGON((0 0,2 0,2 2,0 2,0 0))',4326) WHERE id='31bb854c-7863-5b52-b51d-277145850afe'$q$,'08 geocerca no se reescribe','P0001');
SELECT pg_temp.assert_true((SELECT animal_id='f2935e9e-e433-51fa-8d4d-a0a26d898f7b' FROM telemetry WHERE id='e82d21c2-2627-55ec-b2fd-82b469725a2a'),'09 lectura tardia conserva animal anterior');
SELECT pg_temp.expect_error($q$INSERT INTO telemetry(id,farm_id,device_id,assignment_id,animal_id,session_id,seq,observed_at,received_at,point,gnss_valid,source) VALUES('659c6bc0-30f7-53eb-a0eb-94a074ad1a10','eab52320-d49e-54e6-a56f-0aac26b96b2b','97d6dd52-ea04-5bfd-b441-f0362dac754c','bf7f5a56-2e0c-53ed-894e-8f9d2706bfed','c8245654-e6ca-52e9-a953-4f34060d5069','sesion-1',2,now()-interval '45 minutes',now(),ST_SetSRID(ST_Point(0.5,0.5),4326),true,'academic')$q$,'10 lectura de animal incorrecto rechazada','P0001');
SELECT pg_temp.expect_error($q$INSERT INTO telemetry(id,farm_id,device_id,assignment_id,animal_id,session_id,seq,observed_at,received_at,point,gnss_valid,source) VALUES('eb0a6486-35f8-51e4-9117-4c9f4909a6e2','eab52320-d49e-54e6-a56f-0aac26b96b2b','97d6dd52-ea04-5bfd-b441-f0362dac754c','bf7f5a56-2e0c-53ed-894e-8f9d2706bfed','f2935e9e-e433-51fa-8d4d-a0a26d898f7b','sesion-1',2,now(),now(),ST_SetSRID(ST_Point(0.5,0.5),4326),true,'academic')$q$,'11 captura fuera de asignacion rechazada','P0001');
SELECT pg_temp.expect_error($q$INSERT INTO telemetry(id,farm_id,device_id,assignment_id,animal_id,session_id,seq,observed_at,received_at,point,gnss_valid,source) VALUES('36d9861d-8c01-5470-b56b-1872f2234126','eab52320-d49e-54e6-a56f-0aac26b96b2b','97d6dd52-ea04-5bfd-b441-f0362dac754c','bf7f5a56-2e0c-53ed-894e-8f9d2706bfed','f2935e9e-e433-51fa-8d4d-a0a26d898f7b','sesion-1',1,now()-interval '45 minutes',now(),ST_SetSRID(ST_Point(0.5,0.5),4326),true,'academic')$q$,'12 uplink duplicado rechazado','23505');
SELECT pg_temp.expect_error($q$UPDATE telemetry SET quality='{}' WHERE id='e82d21c2-2627-55ec-b2fd-82b469725a2a'$q$,'13 telemetria inmutable','P0001');
SELECT pg_temp.assert_true((SELECT count(*) FROM telemetry)=1 AND (SELECT count(*) FROM telemetry_receptions)=2,'14 multiantena no duplica lectura');
SELECT pg_temp.assert_true(EXISTS(SELECT 1 FROM pending_changes WHERE id='6abf4e39-46a0-58d1-b97f-fcb1fbe99cdd') AND NOT EXISTS(SELECT 1 FROM health_events),'15 solicitud pendiente no altera salud efectiva');
SELECT pg_temp.expect_error($q$INSERT INTO change_decisions(request_id,decided_by,decision) VALUES('6abf4e39-46a0-58d1-b97f-fcb1fbe99cdd','0a2d603c-a2c1-5443-a9f9-24772c4da67c','approved')$q$,'16 trabajador no aprueba su propuesta','P0001');
SELECT pg_temp.expect_error($q$INSERT INTO change_decisions(request_id,decided_by,decision) VALUES('6abf4e39-46a0-58d1-b97f-fcb1fbe99cdd','b80b7796-014f-5044-9198-4015dace5fda','approved')$q$,'17 veterinario no revisa propuestas del trabajador','P0001');
SELECT pg_temp.expect_error($q$INSERT INTO change_decisions(request_id,decided_by,decision) VALUES('6abf4e39-46a0-58d1-b97f-fcb1fbe99cdd','1886724f-5b09-5ec6-a6fd-f7bab0df80cc','approved')$q$,'18 dueno ajeno no aprueba','P0001');
SELECT pg_temp.expect_error($q$INSERT INTO change_requests(id,farm_id,requested_by,membership_id,action,animal_holding_id,animal_id,payload,idempotency_key) VALUES('2f3e50e1-9cc3-50a2-8975-ccd2764b6b5b','eab52320-d49e-54e6-a56f-0aac26b96b2b','0a2d603c-a2c1-5443-a9f9-24772c4da67c','9e5632dc-4438-5495-b102-e096b596b26a','animal_profile','95c2c19d-132b-5f6d-8a15-1805e14704f8','f2935e9e-e433-51fa-8d4d-a0a26d898f7b','{"description":"registro sintetico"}','5e5708e2-8b41-509a-a874-5c8ec73752c6')$q$,'19 trabajador no solicita campos de ficha tecnica','P0001');
SELECT pg_temp.expect_error($q$INSERT INTO health_events(farm_id,animal_holding_id,request_id,event_type,operation,recorded_by,description) VALUES('eab52320-d49e-54e6-a56f-0aac26b96b2b','95c2c19d-132b-5f6d-8a15-1805e14704f8','6abf4e39-46a0-58d1-b97f-fcb1fbe99cdd','observation','record','0a2d603c-a2c1-5443-a9f9-24772c4da67c','sin decision')$q$,'20 sin decision no hay evento efectivo','P0002');
SELECT pg_temp.expect_error($q$UPDATE change_decisions SET reason='cambio' WHERE request_id='6abf4e39-46a0-58d1-b97f-fcb1fbe99cdd'$q$,'21 decision inmutable','P0001');
SELECT pg_temp.expect_error($q$INSERT INTO change_applications(request_id,entity_type,entity_id) VALUES('6abf4e39-46a0-58d1-b97f-fcb1fbe99cdd','health_events','ea898d80-694e-573a-827b-7900156fa08f')$q$,'22 rechazo no permite aplicacion','P0001');
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
SELECT pg_temp.assert_true(EXISTS(SELECT 1 FROM effective_health_events WHERE id='114dcdc4-5237-5932-b89c-f2fab5755804'),'23 veterinario aplica salud directamente');
SELECT pg_temp.expect_error($q$DELETE FROM health_events WHERE id='114dcdc4-5237-5932-b89c-f2fab5755804'$q$,'24 salud historica no se borra','P0001');
SELECT pg_temp.expect_error($q$INSERT INTO change_decisions(request_id,decided_by,decision) VALUES('7775b3af-dd0d-5e25-b3b1-3db852aed147','0a2d603c-a2c1-5443-a9f9-24772c4da67c','direct')$q$,'25 trabajador sin confianza no aplica directo','P0002');
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
SELECT pg_temp.assert_true(EXISTS(SELECT 1 FROM maintenance WHERE id='dbca19ef-6965-5648-a02f-290c02719925'),'26 confianza permite bateria con evidencia');
SELECT pg_temp.expect_error($q$INSERT INTO change_applications(request_id,entity_type,entity_id) VALUES('7775b3af-dd0d-5e25-b3b1-3db852aed147','maintenance','dbca19ef-6965-5648-a02f-290c02719925')$q$,'27 solicitud no se aplica dos veces','23505');
SELECT pg_temp.expect_error($q$DO $b$ BEGIN INSERT INTO change_decisions(request_id,decided_by,decision) VALUES('e939388d-8fe8-58c0-aac7-ef363a1dc81d','63e02029-ff09-549d-a85a-5d8641a63193','direct'); SET CONSTRAINTS ALL IMMEDIATE; END $b$$q$,'28 decision aceptada sin aplicacion impide commit','P0001');
SELECT pg_temp.assert_true((SELECT count(*) FROM health_events)=2 AND (SELECT count(*) FROM effective_health_events)=1,'29 correccion conserva original y cambia vista efectiva');
SELECT pg_temp.expect_error($q$INSERT INTO health_events(farm_id,animal_holding_id,request_id,event_type,operation,target_event_id,recorded_by,description) VALUES('eab52320-d49e-54e6-a56f-0aac26b96b2b','95c2c19d-132b-5f6d-8a15-1805e14704f8','189f48c0-6a09-5e48-8f70-7b9f38afc8e6','observation','correct','114dcdc4-5237-5932-b89c-f2fab5755804','b80b7796-014f-5044-9198-4015dace5fda','otra correccion')$q$,'30 evento no admite dos sucesores','23505');
SELECT pg_temp.expect_error($q$DELETE FROM audit_log$q$,'31 auditoria inmutable','P0001');
SELECT pg_temp.assert_true((SELECT installed_collars=1 AND animals=2 FROM kpi_inventory_by_owner WHERE account_id='3011abe0-6d5c-55c7-a849-237a46c59b72'),'32 KPIs de inventario coherentes');
SET CONSTRAINTS ALL IMMEDIATE;
SELECT '32 comprobaciones SQL superadas; datos sinteticos revertidos' AS resultado;
ROLLBACK;
